import 'package:flutter/material.dart';
import '../models/music_models.dart'; import '../services/musicbrainz_api.dart'; import '../widgets/state_views.dart';
class AlbumDetailPage extends StatefulWidget { const AlbumDetailPage({super.key,required this.album}); final ReleaseGroup album; @override State<AlbumDetailPage> createState()=>_AlbumDetailPageState(); }
class _AlbumDetailPageState extends State<AlbumDetailPage>{final _api=MusicBrainzApi();late Future<AlbumDetail> _future;@override void initState(){super.initState();_future=_api.albumDetail(widget.album);}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Detail Album')),body:FutureBuilder<AlbumDetail>(future:_future,builder:(context,snapshot){if(snapshot.connectionState==ConnectionState.waiting)return const LoadingView(text:'Memuat track list...');if(snapshot.hasError)return ErrorView(message:snapshot.error.toString(),onRetry:()=>setState(()=>_future=_api.albumDetail(widget.album)));final detail=snapshot.data!;return ListView(padding:const EdgeInsets.all(20),children:[Container(height:185,decoration:BoxDecoration(color:const Color(0xff9b8cff),borderRadius:BorderRadius.circular(24)),child:const Icon(Icons.album_rounded,size:96,color:Colors.black)),const SizedBox(height:20),Text(detail.album.title,style:const TextStyle(fontSize:27,fontWeight:FontWeight.w900)),const SizedBox(height:8),Text('${detail.album.primaryType??'Rilisan'} • ${detail.releaseDate??detail.album.firstReleaseDate??'Tanggal tidak tersedia'}'),if(detail.label!=null) Padding(padding:const EdgeInsets.only(top:4),child:Text('Label: ${detail.label}')),const SizedBox(height:26),const Text('Track List',style:TextStyle(fontSize:20,fontWeight:FontWeight.bold)),const SizedBox(height:8),if(detail.tracks.isEmpty)const Text('Track list belum tersedia pada data API.') else ...detail.tracks.map((track)=>ListTile(contentPadding:EdgeInsets.zero,leading:CircleAvatar(radius:16,child:Text(track.number)),title:Text(track.title),trailing:Text(track.duration)))]);}));}
